import { describe, it, expect } from 'vitest';
import { parseRow } from './csv.js';

describe('parseRow', () => {
  it('splits plain unquoted fields', () => {
    expect(parseRow('a,b,c')).toEqual(['a', 'b', 'c']);
  });
});
